/* ---------------------------------------------------------------
   HELPERS
--------------------------------------------------------------- */
const normalize = (s) => (s || "").toLowerCase().replace(/[^a-z0-9]/g, "");
const uid = () => `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
const money = (n) =>
  isFinite(n) ? n.toLocaleString("en-US", { style: "currency", currency: "USD" }) : "—";
const fmtMg = (n) => `${(Math.round(n * 100) / 100).toString()} mg`;

function buildDatabase(vendors, protocols) {
  const map = {};
  vendors.forEach((v) => {
    if (!v.name) return;
    const key = normalize(v.name);
    if (!map[key]) map[key] = { key, displayName: v.name, protocol: null, vendors: [] };
    map[key].vendors.push({
      id: `${key}-${map[key].vendors.length}`,
      format: v.format || "Vial",
      strengthMg: Number(v.strengthMg),
      wholesalePrice: Number(v.wholesalePrice),
    });
  });
  protocols.forEach((p) => {
    if (!p.name) return;
    const key = normalize(p.name);
    if (!map[key]) map[key] = { key, displayName: p.name, protocol: null, vendors: [] };
    map[key].protocol = {
      doseMg: Number(p.doseMg) || 0,
      freqPerWeek: Number(p.freqPerWeek) || 0,
      durationWeeks: Number(p.durationWeeks) || 0,
    };
    if (map[key].vendors.length === 0) map[key].displayName = p.name;
  });
  return Object.values(map).sort((a, b) => a.displayName.localeCompare(b.displayName));
}

function totalMgOf(config) {
  return (Number(config.doseMg) || 0) * (Number(config.freqPerWeek) || 0) * (Number(config.durationWeeks) || 0);
}

function computeVendorLine(vendor, totalMg) {
  const strengthMg = vendor.strengthMg || 0;
  const unitsNeeded = totalMg > 0 && strengthMg > 0 ? Math.ceil(totalMg / strengthMg) : 0;
  const costOffice = unitsNeeded * vendor.wholesalePrice;
  const perMgRate = strengthMg > 0 ? vendor.wholesalePrice / strengthMg : 0;
  const wasteMg = unitsNeeded * strengthMg - totalMg;
  return { unitsNeeded, costOffice, perMgRate, wasteMg: wasteMg > 0 ? wasteMg : 0 };
}

function pickField(row, candidates) {
  for (const k of Object.keys(row)) {
    if (candidates.includes(k.trim().toLowerCase())) return row[k];
  }
  return undefined;
}

function parseVendorRow(r) {
  const num = (v) => parseFloat(String(v || "").replace(/[^0-9.]/g, ""));
  // Sums every "<number>mg" amount found (handles combo products written
  // like "10mg/10mg, 3mL" — two peptides in one pen — as 10+10=20mg total,
  // correctly ignoring the "3mL" volume). Plain cells like "10" still work.
  const parseStrengthMg = (v) => {
    const str = String(v ?? "");
    const mgMatches = [...str.matchAll(/(\d+(?:\.\d+)?)\s*mg/gi)];
    if (mgMatches.length) return mgMatches.reduce((sum, m) => sum + parseFloat(m[1]), 0);
    return num(str);
  };
  return {
    name: (pickField(r, ["product", "peptide", "name", "item", "product name", "peptide name"]) || "").trim(),
    format: (pickField(r, ["format", "delivery", "type", "delivery format"]) || "Vial").trim(),
    strengthMg: parseStrengthMg(pickField(r, ["strength", "size", "strength (mg)", "strength_mg", "mg", "volume"])),
    wholesalePrice: num(pickField(r, ["price", "wholesale", "cost", "wholesale price", "office cost"])),
  };
}

function parseProtocolRow(r) {
  const num = (v) => parseFloat(String(v || "").replace(/[^0-9.]/g, ""));
  return {
    name: (pickField(r, ["product", "peptide", "name", "item", "product name", "peptide name"]) || "").trim(),
    doseMg: num(pickField(r, ["dose", "dose_mg", "dosage", "dose (mg)"])),
    freqPerWeek: num(pickField(r, ["frequency", "freq", "times per week", "frequency_per_week", "freq/week"])),
    durationWeeks: num(pickField(r, ["duration", "weeks", "duration_weeks", "course length", "duration (weeks)"])),
  };
}

/* ---------------------------------------------------------------
   SMALL UI PRIMITIVES
--------------------------------------------------------------- */
function Tag({ tone, children, icon }) {
  const tones = {
    amber: { bg: C.amberSoft, fg: C.amber },
    clay: { bg: C.claySoft, fg: C.clay },
    teal: { bg: C.tealSoft, fg: C.tealDark },
    green: { bg: C.successSoft, fg: C.success },
  };
  const t = tones[tone] || tones.teal;
  return (
    <span
      className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-semibold"
      style={{ background: t.bg, color: t.fg, fontFamily: FONT_BODY }}
    >
      {icon} {children}
    </span>
  );
}

function NumField({ label, value, onChange, step = "0.01", suffix }) {
  return (
    <label className="flex flex-col gap-1 text-xs" style={{ color: C.inkSoft, fontFamily: FONT_BODY }}>
      {label}
      <div className="flex items-center gap-1">
        <input
          type="number"
          step={step}
          value={value}
          onChange={(e) => onChange(parseFloat(e.target.value) || 0)}
          className="w-full px-2 py-1.5 rounded-md text-sm outline-none"
          style={{ border: `1px solid ${C.line}`, color: C.ink, fontFamily: FONT_MONO, background: C.card }}
        />
        {suffix && <span className="text-xs" style={{ color: C.inkSoft }}>{suffix}</span>}
      </div>
    </label>
  );
}

function SectionTitle({ eyebrow, title, right }) {
  return (
    <div className="flex items-end justify-between mb-3">
      <div>
        {eyebrow && (
          <div className="text-xs uppercase tracking-wide mb-0.5" style={{ color: C.amber, fontFamily: FONT_BODY, letterSpacing: "0.08em" }}>
            {eyebrow}
          </div>
        )}
        <div className="text-lg font-semibold" style={{ color: C.ink, fontFamily: FONT_DISPLAY }}>
          {title}
        </div>
      </div>
      {right}
    </div>
  );
}

/* ---------------------------------------------------------------
   MAIN APP
--------------------------------------------------------------- */
export default function GajerPeptideApp() {
  const [rawVendors, setRawVendors] = useState(SAMPLE_VENDORS);
  const [rawProtocols, setRawProtocols] = useState(SAMPLE_PROTOCOLS);
  const peptideDatabase = useMemo(() => buildDatabase(rawVendors, rawProtocols), [rawVendors, rawProtocols]);

  const [idToken, setIdToken] = useState(null);
  const [authProfile, setAuthProfile] = useState(null);
  const [authError, setAuthError] = useState("");
  const [catalogError, setCatalogError] = useState("");
  const [patientIdInput, setPatientIdInput] = useState("");
  const [activePatientId, setActivePatientId] = useState(null);
  const [patientHistory, setPatientHistory] = useState({});
  const [patientIndex, setPatientIndex] = useState([]);
  const [patientIdError, setPatientIdError] = useState("");
  const [activeTab, setActiveTab] = useState("search");
  const [patientMode, setPatientMode] = useState(false);

  const [query, setQuery] = useState("");
  const [selectedKey, setSelectedKey] = useState(null);
  const [config, setConfig] = useState({ doseMg: 0, freqPerWeek: 0, durationWeeks: 0 });
  const [durationUnit, setDurationUnit] = useState("weeks"); // "weeks" | "days" — display/input only, stored value stays in weeks
  const [selectedVendorId, setSelectedVendorId] = useState(null);
  const [multiplier, setMultiplier] = useState(3);
  const [flatOverride, setFlatOverride] = useState(null);
  const [useFlat, setUseFlat] = useState(false);

  const [planCart, setPlanCart] = useState([]);

  // Custom Blend builder — a doctor-compounded formulation, not a vendor-catalog item
  const [blendName, setBlendName] = useState("");
  const [blendFreqPerWeek, setBlendFreqPerWeek] = useState(7);
  const [blendDurationWeeks, setBlendDurationWeeks] = useState(4);
  const [blendDurationUnit, setBlendDurationUnit] = useState("weeks"); // "weeks" | "days" — display/input only
  const [blendDoseVolumeMl, setBlendDoseVolumeMl] = useState(0);
  const [blendComponents, setBlendComponents] = useState([]); // {key, name, doseMg, vendorId}
  const [blendMultiplier, setBlendMultiplier] = useState(3);
  const [blendFlatOverride, setBlendFlatOverride] = useState(null);
  const [blendUseFlat, setBlendUseFlat] = useState(false);
  const [blendComponentQuery, setBlendComponentQuery] = useState("");
  const [blendTemplates, setBlendTemplates] = useState([]);

  const [exportRecord, setExportRecord] = useState(null);
  const [exportPreset, setExportPreset] = useState("internal");
  const [fields, setFields] = useState({
    protocol: true, vendor: true, perMg: true, office: true, patient: true,
  });

  const [importStatus, setImportStatus] = useState({ vendors: null, protocols: null });

  /* ---------- Google Sign-In ---------- */
  useEffect(() => {
    function init() {
      if (!window.google?.accounts?.id) return;
      window.google.accounts.id.initialize({
        client_id: GOOGLE_CLIENT_ID,
        callback: handleCredentialResponse,
      });
      const el = document.getElementById("google-signin-button");
      if (el) window.google.accounts.id.renderButton(el, { theme: "outline", size: "medium", text: "signin_with" });
    }
    if (window.google?.accounts?.id) {
      init();
    } else {
      const script = document.createElement("script");
      script.src = "https://accounts.google.com/gsi/client";
      script.async = true;
      script.onload = init;
      document.body.appendChild(script);
    }
  }, []);

  function handleCredentialResponse(response) {
    const token = response.credential;
    setIdToken(token);
    setAuthError("");
    try {
      const payload = JSON.parse(atob(token.split(".")[1].replace(/-/g, "+").replace(/_/g, "/")));
      setAuthProfile({ email: payload.email, name: payload.name || payload.email });
    } catch {
      setAuthProfile(null);
    }
  }

  function signOut() {
    setIdToken(null);
    setAuthProfile(null);
    try { window.google?.accounts?.id?.disableAutoSelect(); } catch {}
  }

  async function authFetch(path, options = {}) {
    if (!idToken) throw new Error("Please sign in with Google first.");
    const res = await fetch(`${API_BASE}${path}`, {
      ...options,
      headers: { "Content-Type": "application/json", ...(options.headers || {}), Authorization: `Bearer ${idToken}` },
    });
    const data = await res.json().catch(() => ({}));
    if (!res.ok) throw new Error(data.error || `Request failed (${res.status})`);
    return data;
  }

  /* ---------- backend: fetch the real catalog once signed in ---------- */
  useEffect(() => {
    if (!idToken) return;
    (async () => {
      try {
        const data = await authFetch("/catalog");
        setRawVendors(data.vendors || []);
        setRawProtocols(data.protocols || []);
        setCatalogError("");
      } catch (err) {
        setCatalogError(err.message);
      }
    })();
  }, [idToken]);

  /* ---------- backend: load known patient IDs once signed in ---------- */
  useEffect(() => {
    if (!idToken) { setPatientIndex([]); return; }
    (async () => {
      try {
        const data = await authFetch("/patients");
        setPatientIndex(data.patients || []);
      } catch {
        setPatientIndex([]);
      }
    })();
  }, [idToken]);

  function addPatientIdLocally(id) {
    setPatientIndex((prev) => (prev.includes(id) ? prev : [...prev, id].sort()));
  }

  function generatePatientId() {
    let candidate;
    do {
      candidate = `GJ-${Math.floor(1000 + Math.random() * 9000)}`;
    } while (patientIndex.includes(candidate));
    return candidate;
  }

  async function createNewPatient(customId) {
    if (!idToken) { setPatientIdError("Please sign in with Google first."); return; }
    const id = (customId || "").trim() || generatePatientId();
    if (patientIndex.includes(id)) {
      setPatientIdError(`Patient ID "${id}" already exists — loading their existing record instead.`);
      setActivePatientId(id);
      setPatientIdInput(id);
      return;
    }
    setPatientIdError("");
    try {
      await authFetch("/patients", { method: "POST", body: JSON.stringify({ patientId: id }) });
      addPatientIdLocally(id);
      setPatientHistory((prev) => ({ ...prev, [id]: [] }));
      setActivePatientId(id);
      setPatientIdInput(id);
    } catch (err) {
      setPatientIdError(err.message);
    }
  }

  function loadExistingPatient(id) {
    const trimmed = (id || "").trim();
    if (!trimmed) return;
    if (!idToken) { setPatientIdError("Please sign in with Google first."); return; }
    if (!patientIndex.includes(trimmed)) {
      setPatientIdError(`No existing record for "${trimmed}" yet — use "Create New" to start one.`);
      return;
    }
    setPatientIdError("");
    setActivePatientId(trimmed);
  }

  /* ---------- storage: load saved blend templates on mount ---------- */
  useEffect(() => {
    try {
      const raw = localStorage.getItem("gajer-blend-templates");
      setBlendTemplates(raw ? JSON.parse(raw) : []);
    } catch {
      setBlendTemplates([]);
    }
  }, []);

  /* ---------- backend: load a patient's quote history ---------- */
  useEffect(() => {
    if (!activePatientId || !idToken) return;
    (async () => {
      try {
        const data = await authFetch(`/quotes?patientId=${encodeURIComponent(activePatientId)}`);
        setPatientHistory((prev) => ({ ...prev, [activePatientId]: data.records || [] }));
      } catch {
        setPatientHistory((prev) => ({ ...prev, [activePatientId]: prev[activePatientId] || [] }));
      }
    })();
  }, [activePatientId, idToken]);

  // Patient Mode always defaults OFF on a new patient — never carries over.
  useEffect(() => {
    setPatientMode(false);
  }, [activePatientId]);

  const saveRecord = useCallback(
    async (record) => {
      if (!activePatientId) return;
      if (!idToken) { setPatientIdError("Please sign in with Google first."); return; }
      try {
        const saved = await authFetch("/quotes", {
          method: "POST",
          body: JSON.stringify({ patientId: activePatientId, ...record }),
        });
        setPatientHistory((prev) => ({ ...prev, [activePatientId]: [saved, ...(prev[activePatientId] || [])] }));
        addPatientIdLocally(activePatientId);
      } catch (err) {
        setPatientIdError(err.message);
      }
    },
    [activePatientId, idToken]
  );

  /* ---------- derived selection ---------- */
  const selectedPeptide = useMemo(
    () => peptideDatabase.find((p) => p.key === selectedKey) || null,
    [peptideDatabase, selectedKey]
  );
  const totalMg = useMemo(() => totalMgOf(config), [config]);
  const vendorRows = useMemo(() => {
    if (!selectedPeptide) return [];
    const rows = selectedPeptide.vendors.map((v) => ({ ...v, computed: computeVendorLine(v, totalMg) }));
    const withCost = rows.filter((r) => r.computed.costOffice > 0);
    const min = withCost.length ? Math.min(...withCost.map((r) => r.computed.costOffice)) : null;
    const max = withCost.length ? Math.max(...withCost.map((r) => r.computed.costOffice)) : null;
    return rows.map((r) => ({
      ...r,
      isCheapest: min !== null && r.computed.costOffice === min && min !== max,
      isPriciest: max !== null && r.computed.costOffice === max && min !== max,
    }));
  }, [selectedPeptide, totalMg]);

  const selectedVendor = vendorRows.find((v) => v.id === selectedVendorId) || vendorRows[0] || null;
  const officeCost = selectedVendor ? selectedVendor.computed.costOffice : 0;
  const patientCost = useFlat && flatOverride != null ? flatOverride : officeCost * multiplier;

  function selectPeptide(key) {
    const p = peptideDatabase.find((x) => x.key === key);
    setSelectedKey(key);
    if (p && p.protocol) setConfig({ ...p.protocol });
    else setConfig({ doseMg: 0, freqPerWeek: 0, durationWeeks: 0 });
    setDurationUnit("weeks");
    setMultiplier(3);
    setFlatOverride(null);
    setUseFlat(false);
    setSelectedVendorId(p && p.vendors.length ? p.vendors[0].id : null);
  }

  function resetToStandard() {
    if (selectedPeptide && selectedPeptide.protocol) setConfig({ ...selectedPeptide.protocol });
    setDurationUnit("weeks");
  }

  function clearProtocol() {
    setSelectedKey(null);
    setSelectedVendorId(null);
    setConfig({ doseMg: 0, freqPerWeek: 0, durationWeeks: 0 });
    setDurationUnit("weeks");
    setMultiplier(3);
    setFlatOverride(null);
    setUseFlat(false);
    setQuery("");
  }

  function currentLineSnapshot() {
    return {
      key: selectedPeptide.key,
      name: selectedPeptide.displayName,
      config: { ...config },
      totalMg,
      vendor: selectedVendor ? { format: selectedVendor.format, strengthMg: selectedVendor.strengthMg, wholesalePrice: selectedVendor.wholesalePrice } : null,
      unitsNeeded: selectedVendor ? selectedVendor.computed.unitsNeeded : 0,
      officeCost,
      multiplier,
      flatOverride: useFlat ? flatOverride : null,
      patientCost,
    };
  }

  function addToPlan() {
    if (!selectedPeptide || !selectedVendor) return;
    setPlanCart((prev) => [...prev, { ...currentLineSnapshot(), lineId: uid(), type: "single" }]);
  }

  function removePlanLine(lineId) {
    setPlanCart((prev) => prev.filter((l) => l.lineId !== lineId));
  }

  function updatePlanLine(lineId, patch) {
    setPlanCart((prev) =>
      prev.map((l) => {
        if (l.lineId !== lineId) return l;
        const merged = { ...l, ...patch };
        const office = merged.type === "blend" ? merged.officeCost : merged.unitsNeeded * merged.vendor.wholesalePrice;
        merged.officeCost = office;
        merged.patientCost = merged.flatOverride != null ? merged.flatOverride : office * merged.multiplier;
        return merged;
      })
    );
  }

  function flattenPlanCartForSave(cart) {
    const flat = [];
    cart.forEach((l) => {
      if (l.type === "blend") {
        l.components.forEach((comp) => flat.push({ ...comp, groupLabel: l.name }));
      } else {
        flat.push({ ...l });
      }
    });
    return flat;
  }

  function setAllMultipliers(m) {
    setPlanCart((prev) =>
      prev.map((l) => ({ ...l, multiplier: m, flatOverride: null, patientCost: l.officeCost * m }))
    );
  }

  const planTotals = planCart.reduce(
    (acc, l) => ({ office: acc.office + l.officeCost, patient: acc.patient + l.patientCost }),
    { office: 0, patient: 0 }
  );

  function saveSingleQuote() {
    if (!selectedPeptide || !selectedVendor || !activePatientId) return;
    saveRecord({ type: "single", lines: [currentLineSnapshot()], totalOffice: officeCost, totalPatient: patientCost });
  }

  function savePlanQuote() {
    if (!planCart.length || !activePatientId) return;
    const lines = flattenPlanCartForSave(planCart);
    saveRecord({ type: "plan", lines, totalOffice: planTotals.office, totalPatient: planTotals.patient });
    setPlanCart([]);
  }

  /* ---------- Custom Blend builder logic ---------- */
  function addBlendComponent(key) {
    const p = peptideDatabase.find((x) => x.key === key);
    if (!p || blendComponents.some((c) => c.key === key)) return;
    setBlendComponents((prev) => [
      ...prev,
      { key, name: p.displayName, doseMg: p.protocol ? p.protocol.doseMg : 0, vendorId: p.vendors.length ? p.vendors[0].id : null },
    ]);
  }
  function removeBlendComponent(key) {
    setBlendComponents((prev) => prev.filter((c) => c.key !== key));
  }
  function updateBlendComponent(key, patch) {
    setBlendComponents((prev) => prev.map((c) => (c.key === key ? { ...c, ...patch } : c)));
  }
  function resetBlendBuilder() {
    setBlendName(""); setBlendFreqPerWeek(7); setBlendDurationWeeks(4); setBlendDurationUnit("weeks"); setBlendDoseVolumeMl(0);
    setBlendComponents([]); setBlendMultiplier(3); setBlendFlatOverride(null); setBlendUseFlat(false);
  }

  const blendComputed = useMemo(() => {
    return blendComponents.map((c) => {
      const p = peptideDatabase.find((x) => x.key === c.key);
      const vendorOptions = p ? p.vendors : [];
      const vendor = vendorOptions.find((v) => v.id === c.vendorId) || vendorOptions[0] || null;
      const totalMg = (Number(c.doseMg) || 0) * blendFreqPerWeek * blendDurationWeeks;
      const computed = vendor ? computeVendorLine(vendor, totalMg) : { unitsNeeded: 0, costOffice: 0, perMgRate: 0, wasteMg: 0 };
      return { ...c, vendorOptions, vendor, totalMg, computed };
    });
  }, [blendComponents, peptideDatabase, blendFreqPerWeek, blendDurationWeeks]);

  const blendOfficeTotal = blendComputed.reduce((s, c) => s + c.computed.costOffice, 0);
  const blendPatientTotal = blendUseFlat && blendFlatOverride != null ? blendFlatOverride : blendOfficeTotal * blendMultiplier;
  const blendDoseUnits = blendDoseVolumeMl > 0 ? Math.round(blendDoseVolumeMl * 100) : null;
  const blendDisplayName = blendName.trim() || blendComponents.map((c) => c.name).join(" + ") || "Untitled blend";

  function blendSnapshotLines() {
    return blendComputed.map((c) => ({
      key: c.key,
      name: c.name,
      config: { doseMg: c.doseMg, freqPerWeek: blendFreqPerWeek, durationWeeks: blendDurationWeeks },
      totalMg: c.totalMg,
      vendor: c.vendor ? { format: c.vendor.format, strengthMg: c.vendor.strengthMg, wholesalePrice: c.vendor.wholesalePrice } : null,
      unitsNeeded: c.computed.unitsNeeded,
      officeCost: c.computed.costOffice,
      multiplier: blendMultiplier,
      flatOverride: null,
      patientCost: c.computed.costOffice * blendMultiplier,
    }));
  }

  function saveCustomBlendQuote() {
    if (!blendComponents.length || !activePatientId) return;
    saveRecord({
      type: "customblend",
      blendName: blendDisplayName,
      schedule: { freqPerWeek: blendFreqPerWeek, durationWeeks: blendDurationWeeks, doseVolumeMl: blendDoseVolumeMl },
      lines: blendSnapshotLines(),
      totalOffice: blendOfficeTotal,
      totalPatient: blendPatientTotal,
    });
    resetBlendBuilder();
  }

  function addBlendToPlan() {
    if (!blendComponents.length) return;
    setPlanCart((prev) => [
      ...prev,
      {
        lineId: uid(),
        type: "blend",
        name: blendDisplayName,
        schedule: { freqPerWeek: blendFreqPerWeek, durationWeeks: blendDurationWeeks, doseVolumeMl: blendDoseVolumeMl },
        components: blendSnapshotLines(),
        officeCost: blendOfficeTotal,
        multiplier: blendMultiplier,
        flatOverride: blendUseFlat ? blendFlatOverride : null,
        patientCost: blendPatientTotal,
      },
    ]);
    resetBlendBuilder();
  }

  async function saveBlendTemplate() {
    if (!blendComponents.length) return;
    const tmpl = {
      id: uid(),
      name: blendDisplayName,
      freqPerWeek: blendFreqPerWeek,
      durationWeeks: blendDurationWeeks,
      doseVolumeMl: blendDoseVolumeMl,
      components: blendComponents.map((c) => ({ key: c.key, name: c.name, doseMg: c.doseMg, vendorId: c.vendorId })),
    };
    const next = [...blendTemplates.filter((t) => t.name !== tmpl.name), tmpl];
    setBlendTemplates(next);
    try { localStorage.setItem("gajer-blend-templates", JSON.stringify(next)); } catch {}
  }
  function loadBlendTemplate(tmpl) {
    setBlendName(tmpl.name);
    setBlendFreqPerWeek(tmpl.freqPerWeek);
    setBlendDurationWeeks(tmpl.durationWeeks);
    setBlendDurationUnit("weeks");
    setBlendDoseVolumeMl(tmpl.doseVolumeMl || 0);
    setBlendComponents(tmpl.components.map((c) => ({ ...c })));
  }
  async function deleteBlendTemplate(id) {
    const next = blendTemplates.filter((t) => t.id !== id);
    setBlendTemplates(next);
    try { localStorage.setItem("gajer-blend-templates", JSON.stringify(next)); } catch {}
  }

  const blendComponentResults = useMemo(() => {
    const q = blendComponentQuery.trim().toLowerCase();
    return peptideDatabase.filter((p) => !blendComponents.some((c) => c.key === p.key) && (!q || p.displayName.toLowerCase().includes(q)));
  }, [peptideDatabase, blendComponents, blendComponentQuery]);

  /* ---------- CSV import ---------- */
  function handleVendorFile(file) {
    if (!file) return;
    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: (results) => {
        const rows = results.data.map(parseVendorRow).filter((r) => r.name && r.strengthMg > 0 && r.wholesalePrice > 0);
        setRawVendors(rows);
        setImportStatus((s) => ({ ...s, vendors: `${rows.length} vendor listings loaded from "${file.name}"` }));
      },
    });
  }
  function handleProtocolFile(file) {
    if (!file) return;
    Papa.parse(file, {
      header: true,
      skipEmptyLines: true,
      complete: (results) => {
        const rows = results.data.map(parseProtocolRow).filter((r) => r.name);
        setRawProtocols(rows);
        setImportStatus((s) => ({ ...s, protocols: `${rows.length} protocols loaded from "${file.name}"` }));
      },
    });
  }
  function resetSampleData() {
    setRawVendors(SAMPLE_VENDORS);
    setRawProtocols(SAMPLE_PROTOCOLS);
    setImportStatus({ vendors: null, protocols: null });
  }

  const unmatchedProtocolOnly = peptideDatabase.filter((p) => p.protocol && p.vendors.length === 0);
  const unmatchedVendorOnly = peptideDatabase.filter((p) => !p.protocol && p.vendors.length > 0);

  const filteredList = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return peptideDatabase;
    return peptideDatabase.filter((p) => p.displayName.toLowerCase().includes(q));
  }, [peptideDatabase, query]);

  const historyList = activePatientId ? patientHistory[activePatientId] || [] : [];

  /* ---------------------------------------------------------------
     RENDER
  --------------------------------------------------------------- */
  return (
    <div style={{ background: C.paper, minHeight: "100%", fontFamily: FONT_BODY, color: C.ink, position: "relative", overflow: "hidden" }} className="w-full">
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Archivo:wght@500;600;700;800&family=Inter:wght@400;500;600;700&family=Cormorant+Garamond:ital,wght@1,500;1,600&family=IBM+Plex+Mono:wght@400;500;600&display=swap');
        @media print {
          .print-hide { display: none !important; }
          .app-shell { background: white !important; }
          .rounded-xl, .rounded-lg, .rounded-md { box-shadow: none !important; }
        }
        input[type=number]::-webkit-inner-spin-button { opacity: 1; }

        .app-shell .rounded-xl {
          box-shadow: 0 1px 2px rgba(30,27,23,0.05), 0 8px 24px rgba(30,27,23,0.055);
        }
        .app-shell button {
          transition: filter 0.15s ease, transform 0.1s ease, box-shadow 0.15s ease, background-color 0.15s ease, border-color 0.15s ease;
        }
        .app-shell button:hover { filter: brightness(0.96); }
        .app-shell button:active { transform: scale(0.98); }
        .app-shell input, .app-shell select {
          transition: border-color 0.15s ease, box-shadow 0.15s ease;
        }
        .app-shell input:focus, .app-shell select:focus, .app-shell button:focus-visible {
          outline: none;
          border-color: ${C.teal} !important;
          box-shadow: 0 0 0 3px ${C.tealSoft};
        }
        .tgp-row-hover:hover { background: ${C.tealSoft} !important; }
        .tgp-brand-rule {
          height: 3px; border-radius: 2px;
          background: linear-gradient(90deg, ${C.teal} 0%, ${C.amber} 33%, ${C.success} 66%, ${C.clay} 100%);
          opacity: 0.6;
        }
      `}</style>

      <img
        src={LOGO_FULL}
        alt=""
        className="print-hide"
        style={{
          position: "fixed", top: "50%", left: "50%", transform: "translate(-50%,-50%)",
          width: "min(75vw, 900px)", opacity: 0.06, pointerEvents: "none", zIndex: 0, filter: "grayscale(1)",
        }}
      />

      <div className="app-shell max-w-6xl mx-auto px-4 py-5" style={{ position: "relative", zIndex: 1 }}>
        {/* HEADER */}
        <div className="print-hide flex items-center justify-between mb-4">
          <div className="flex items-center gap-3">
            <button
              onClick={() => {
                setPatientMode((v) => !v);
                if (!patientMode && (activeTab === "import" || activeTab === "history")) setActiveTab("search");
              }}
              title="" // intentionally no tooltip/label — discreet by design
              style={{ position: "relative", background: "none", border: "none", padding: 0, cursor: "pointer", lineHeight: 0 }}
            >
              <img src={LOGO_MARK} alt="The Gajer Practice" className="h-10 w-auto" />
              {patientMode && (
                <span
                  style={{
                    position: "absolute", bottom: -1, right: -1, width: 8, height: 8,
                    borderRadius: "50%", background: C.success, border: `1.5px solid ${C.paper}`,
                  }}
                />
              )}
            </button>
            <div>
              <div className="text-xl leading-tight" style={{ fontFamily: FONT_DISPLAY, fontWeight: 600, color: C.ink, letterSpacing: "-0.01em" }}>
                <span style={{ fontFamily: FONT_ACCENT, fontStyle: "italic", fontWeight: 500 }}>The</span> Gajer Practice
              </div>
              <div className="text-xs uppercase" style={{ color: C.inkSoft, letterSpacing: "0.08em" }}>Peptide Protocol &amp; Pricing</div>
            </div>
          </div>
          <div className="flex flex-col items-end gap-1 text-xs" style={{ color: C.inkSoft }}>
            {authProfile ? (
              <div className="flex items-center gap-2">
                <div className="text-right">
                  <div className="text-sm font-medium" style={{ color: C.ink }}>{authProfile.name}</div>
                  <div className="text-xs" style={{ color: C.inkSoft }}>{authProfile.email}</div>
                </div>
                <button onClick={signOut} className="text-xs px-2 py-1 rounded-md" style={{ border: `1px solid ${C.line}`, color: C.inkSoft }}>
                  Sign out
                </button>
              </div>
            ) : (
              <div id="google-signin-button" />
            )}
            {authError && <div className="text-xs" style={{ color: C.clay }}>{authError}</div>}
          </div>
        </div>
        <div className="print-hide tgp-brand-rule mb-4" />

        {catalogError && (
          <div className="print-hide flex items-center gap-2 mb-4 px-3 py-2 rounded-lg text-sm" style={{ background: C.claySoft, color: C.clay }}>
            <AlertCircle size={15} /> Couldn't load your live catalog ({catalogError}) — showing sample data instead.
          </div>
        )}
        {!authProfile && (
          <div className="print-hide flex items-center gap-2 mb-4 px-3 py-2 rounded-lg text-sm" style={{ background: C.tealSoft, color: C.tealDark }}>
            Sign in with your @thegajerpractice.com Google account (top right) to load the real vendor catalog and save patient records.
          </div>
        )}

        {/* PATIENT BAR */}
        <div className="print-hide mb-4 p-3 rounded-xl" style={{ background: C.card, border: `1px solid ${C.line}` }}>
          <div className="flex items-center gap-2 flex-wrap">
            <User size={16} color={C.teal} />
            <input
              value={patientIdInput}
              onChange={(e) => { setPatientIdInput(e.target.value); setPatientIdError(""); }}
              onKeyDown={(e) => { if (e.key === "Enter") loadExistingPatient(patientIdInput); }}
              placeholder="Patient ID (e.g. GJ-1042)"
              list="known-patient-ids"
              className="flex-1 min-w-[160px] px-2 py-1.5 rounded-md text-sm outline-none"
              style={{ border: `1px solid ${C.line}`, fontFamily: FONT_MONO, color: C.ink }}
            />
            <datalist id="known-patient-ids">
              {patientIndex.map((id) => <option key={id} value={id} />)}
            </datalist>
            <button
              onClick={() => loadExistingPatient(patientIdInput)}
              disabled={!patientIdInput.trim()}
              className="px-3 py-1.5 rounded-md text-sm font-medium disabled:opacity-40"
              style={{ background: C.paper, color: C.ink, border: `1px solid ${C.line}` }}
            >
              Find existing
            </button>
            <button
              onClick={() => createNewPatient(patientIdInput)}
              className="flex items-center gap-1.5 px-3 py-1.5 rounded-md text-sm font-medium"
              style={{ background: C.success, color: "white" }}
            >
              <Plus size={14} /> Create new patient
            </button>
            {activePatientId && (
              <Tag tone="green" icon={<CheckCircle2 size={12} />}>
                Active: {activePatientId} · {historyList.length} record{historyList.length === 1 ? "" : "s"}
              </Tag>
            )}
          </div>
          <div className="flex items-center justify-between mt-1.5">
            <div className="text-xs" style={{ color: patientIdError ? C.clay : C.inkSoft }}>
              {patientIdError || "Type an ID and click \u201cCreate new patient\u201d, leave it blank to auto-generate one, or \u201cFind existing\u201d to pull up a saved record."}
            </div>
            {patientIndex.length > 0 && (
              <div className="text-xs" style={{ color: C.inkSoft }}>{patientIndex.length} patient{patientIndex.length === 1 ? "" : "s"} on file</div>
            )}
          </div>
        </div>

        {/* TABS */}
        <div className="print-hide flex gap-1 mb-5 p-1 rounded-xl flex-wrap" style={{ background: "#EAE3D5", boxShadow: "none" }}>
          {[
            ["search", "Search & Quote"],
            ["plan", "Treatment Plan"],
            ["customblend", "Custom Blend"],
            ["history", "Patient History"],
            ["import", "Import Data"],
            ["export", "Export"],
          ]
            .filter(([key]) => !(patientMode && (key === "history" || key === "import")))
            .map(([key, label]) => (
            <button
              key={key}
              onClick={() => setActiveTab(key)}
              className="px-3.5 py-1.5 text-sm font-medium rounded-lg"
              style={{
                color: activeTab === key ? "white" : C.inkSoft,
                background: activeTab === key ? C.teal : "transparent",
                boxShadow: activeTab === key ? "0 2px 6px rgba(58,53,46,0.35)" : "none",
              }}
            >
              {label}
              {key === "plan" && planCart.length > 0 && (
                <span className="ml-1.5 px-1.5 py-0.5 rounded-full text-xs" style={{ background: activeTab === key ? "rgba(255,255,255,0.25)" : C.amberSoft, color: activeTab === key ? "white" : C.amber }}>
                  {planCart.length}
                </span>
              )}
              {key === "customblend" && blendComponents.length > 0 && (
                <span className="ml-1.5 px-1.5 py-0.5 rounded-full text-xs" style={{ background: activeTab === key ? "rgba(255,255,255,0.25)" : C.amberSoft, color: activeTab === key ? "white" : C.amber }}>
                  {blendComponents.length}
                </span>
              )}
            </button>
          ))}
        </div>

        {/* ===================== SEARCH TAB ===================== */}
        {activeTab === "search" && (
          <div className="grid grid-cols-12 gap-4">
            <div className="col-span-12 md:col-span-4">
              <div className="rounded-xl p-3" style={{ background: C.card, border: `1px solid ${C.line}` }}>
                <div className="flex items-center gap-2 mb-3 px-2 py-1.5 rounded-md" style={{ background: C.paper }}>
                  <Search size={15} color={C.inkSoft} />
                  <input
                    value={query}
                    onChange={(e) => setQuery(e.target.value)}
                    placeholder="Search peptide name…"
                    className="flex-1 bg-transparent outline-none text-sm"
                    style={{ color: C.ink }}
                  />
                </div>
                <div className="flex flex-col gap-0.5 max-h-[520px] overflow-y-auto">
                  {filteredList.map((p) => (
                    <button
                      key={p.key}
                      onClick={() => selectPeptide(p.key)}
                      className={`flex items-center justify-between px-2.5 py-2 rounded-md text-left text-sm ${selectedKey === p.key ? "" : "tgp-row-hover"}`}
                      style={{ background: selectedKey === p.key ? C.tealSoft : "transparent", color: C.ink }}
                    >
                      <span>
                        {p.displayName}
                        {(!p.protocol || p.vendors.length === 0) && (
                          <AlertCircle size={12} className="inline ml-1.5 mb-0.5" color={C.clay} />
                        )}
                      </span>
                      <ChevronRight size={14} color={C.inkSoft} />
                    </button>
                  ))}
                  {filteredList.length === 0 && (
                    <div className="text-sm px-2 py-4" style={{ color: C.inkSoft }}>No peptides match that search.</div>
                  )}
                </div>
              </div>
            </div>

            <div className="col-span-12 md:col-span-8">
              {!selectedPeptide && (
                <div className="rounded-xl p-8 text-center" style={{ background: C.card, border: `1px dashed ${C.line}`, color: C.inkSoft }}>
                  Select a peptide from the list to see its protocol and pricing.
                </div>
              )}

              {selectedPeptide && (
                <div className="flex flex-col gap-4">
                  {!selectedPeptide.protocol && (
                    <div className="flex items-center gap-2 px-3 py-2 rounded-lg text-sm" style={{ background: C.claySoft, color: C.clay }}>
                      <AlertCircle size={15} /> No protocol on file for this item yet — enter dose, frequency, and duration manually.
                    </div>
                  )}
                  {selectedPeptide.vendors.length === 0 && (
                    <div className="flex items-center gap-2 px-3 py-2 rounded-lg text-sm" style={{ background: C.claySoft, color: C.clay }}>
                      <AlertCircle size={15} /> No vendor pricing found for this peptide — check the Import Data tab.
                    </div>
                  )}

                  {/* Protocol + customize */}
                  <div className="rounded-xl p-4" style={{ background: C.card, border: `1px solid ${C.line}` }}>
                    <SectionTitle
                      eyebrow="Protocol"
                      title={selectedPeptide.displayName}
                      right={
                        <div className="flex items-center gap-2">
                          {selectedPeptide.protocol && (
                            <button onClick={resetToStandard} className="flex items-center gap-1 text-xs px-2 py-1 rounded-md" style={{ color: C.teal, border: `1px solid ${C.line}` }}>
                              <RotateCcw size={12} /> Reset to standard
                            </button>
                          )}
                          <button onClick={clearProtocol} className="flex items-center gap-1 text-xs px-2 py-1 rounded-md" style={{ color: C.inkSoft, border: `1px solid ${C.line}` }}>
                            <X size={12} /> Clear
                          </button>
                        </div>
                      }
                    />
                    <div className="grid grid-cols-3 gap-3 mb-3">
                      <NumField label="Dose per administration" suffix="mg" value={config.doseMg} onChange={(v) => setConfig((c) => ({ ...c, doseMg: v }))} />
                      <NumField label="Frequency" suffix="per week" step="1" value={config.freqPerWeek} onChange={(v) => setConfig((c) => ({ ...c, freqPerWeek: v }))} />
                      <div className="flex flex-col gap-1 text-xs" style={{ color: C.inkSoft }}>
                        <div className="flex items-center justify-between">
                          <span>Duration</span>
                          <div className="flex rounded-md overflow-hidden" style={{ border: `1px solid ${C.line}` }}>
                            {["weeks", "days"].map((u) => (
                              <button
                                key={u}
                                onClick={() => setDurationUnit(u)}
                                className="px-1.5 py-0.5 text-xs"
                                style={{ background: durationUnit === u ? C.teal : "transparent", color: durationUnit === u ? "white" : C.inkSoft }}
                              >
                                {u}
                              </button>
                            ))}
                          </div>
                        </div>
                        <div className="flex items-center gap-1">
                          <input
                            type="number" step={durationUnit === "days" ? "1" : "0.5"}
                            value={durationUnit === "days" ? Math.round(config.durationWeeks * 7 * 100) / 100 : config.durationWeeks}
                            onChange={(e) => {
                              const v = parseFloat(e.target.value) || 0;
                              setConfig((c) => ({ ...c, durationWeeks: durationUnit === "days" ? v / 7 : v }));
                            }}
                            className="w-full px-2 py-1.5 rounded-md text-sm outline-none"
                            style={{ border: `1px solid ${C.line}`, color: C.ink, fontFamily: FONT_MONO, background: C.card }}
                          />
                          <span className="text-xs">{durationUnit}</span>
                        </div>
                      </div>
                    </div>
                    <div className="text-sm px-3 py-2 rounded-md" style={{ background: C.tealSoft, color: C.tealDark, fontFamily: FONT_MONO }}>
                      Total course requirement: <strong>{fmtMg(totalMg)}</strong>
                    </div>
                  </div>

                  {/* Vendor match table */}
                  <div className="rounded-xl p-4" style={{ background: C.card, border: `1px solid ${C.line}` }}>
                    <SectionTitle eyebrow={patientMode ? "Options" : "Vendor match"} title={patientMode ? "Choose a product option" : "Pricing by product option"} />
                    <div className="flex flex-col gap-2">
                      {vendorRows.map((v) => (
                        <button
                          key={v.id}
                          onClick={() => setSelectedVendorId(v.id)}
                          className="text-left p-3 rounded-lg flex items-center justify-between gap-3"
                          style={{
                            border: `1.5px solid ${selectedVendorId === v.id ? C.teal : C.line}`,
                            borderLeft: patientMode ? `4px solid ${selectedVendorId === v.id ? C.teal : C.line}` : `4px solid ${v.isCheapest ? C.success : v.isPriciest ? C.clay : (selectedVendorId === v.id ? C.teal : C.line)}`,
                            background: selectedVendorId === v.id ? C.tealSoft : C.paper,
                          }}
                        >
                          {patientMode ? (
                            <>
                              <div className="text-sm font-medium" style={{ color: C.ink }}>{v.format} · {v.strengthMg}mg</div>
                              <div className="text-right">
                                <div className="text-sm font-semibold" style={{ color: C.amber, fontFamily: FONT_MONO }}>{money(v.computed.costOffice * multiplier)}</div>
                              </div>
                            </>
                          ) : (
                            <>
                              <div>
                                <div className="text-sm font-medium" style={{ color: C.ink }}>
                                  {v.format} · {v.strengthMg}mg — {money(v.wholesalePrice)}
                                  {v.isCheapest && <Tag tone="green" icon={<TrendingDown size={11} />}>Best value</Tag>}
                                  {v.isPriciest && <Tag tone="clay" icon={<TrendingUp size={11} />}>Highest cost</Tag>}
                                </div>
                                <div className="text-xs mt-1" style={{ color: C.inkSoft, fontFamily: FONT_MONO }}>
                                  {money(v.computed.perMgRate)}/mg · {v.computed.unitsNeeded} unit{v.computed.unitsNeeded === 1 ? "" : "s"} needed
                                  {v.computed.wasteMg > 0 && ` · ${fmtMg(v.computed.wasteMg)} leftover`}
                                </div>
                              </div>
                              <div className="text-right">
                                <div className="text-sm font-semibold" style={{ color: C.ink, fontFamily: FONT_MONO }}>{money(v.computed.costOffice)}</div>
                                <div className="text-xs" style={{ color: C.inkSoft }}>office cost</div>
                              </div>
                            </>
                          )}
                        </button>
                      ))}
                    </div>
                  </div>

                  {/* Pricing / ledger */}
                  {selectedVendor && (
                    <div className="rounded-xl p-4" style={{ background: C.card, border: `1px solid ${C.line}` }}>
                      <SectionTitle eyebrow={patientMode ? "Cost to patient" : "Patient price"} title={patientMode ? selectedPeptide.displayName : "Quote breakdown"} />

                      {patientMode ? (
                        <>
                          <div className="rounded-lg p-5 mb-4 text-center" style={{ background: C.tealSoft }}>
                            <div className="text-3xl font-semibold" style={{ fontFamily: FONT_MONO, color: C.amber }}>{money(patientCost)}</div>
                            <div className="text-xs mt-1" style={{ color: C.inkSoft }}>
                              {config.doseMg}mg · {config.freqPerWeek}×/week · {config.durationWeeks} weeks
                            </div>
                          </div>
                          <div className="flex items-center gap-2 mb-4">
                            <span className="text-sm" style={{ color: C.inkSoft }}>Adjust this price</span>
                            <input
                              type="number" step="1"
                              value={useFlat && flatOverride != null ? flatOverride : Math.round(patientCost)}
                              onChange={(e) => { setUseFlat(true); setFlatOverride(parseFloat(e.target.value) || 0); }}
                              className="w-28 px-2 py-1.5 rounded-md text-sm outline-none"
                              style={{ border: `1px solid ${C.line}`, fontFamily: FONT_MONO }}
                            />
                            {useFlat && (
                              <button onClick={() => { setUseFlat(false); setFlatOverride(null); }} className="text-xs underline" style={{ color: C.inkSoft }}>
                                Reset to standard pricing
                              </button>
                            )}
                          </div>
                        </>
                      ) : (
                        <>
                          <div className="flex flex-wrap items-center gap-3 mb-3">
                            <label className="flex items-center gap-2 text-sm">
                              <input type="checkbox" checked={!useFlat} onChange={() => setUseFlat(false)} />
                              Multiplier
                            </label>
                            <input
                              type="number" step="0.1" value={multiplier} disabled={useFlat}
                              onChange={(e) => setMultiplier(parseFloat(e.target.value) || 0)}
                              className="w-20 px-2 py-1 rounded-md text-sm outline-none disabled:opacity-40"
                              style={{ border: `1px solid ${C.line}`, fontFamily: FONT_MONO }}
                            />
                            <span className="text-sm" style={{ color: C.inkSoft }}>×</span>
                            <span className="text-sm" style={{ color: C.inkSoft }}>— or —</span>
                            <label className="flex items-center gap-2 text-sm">
                              <input type="checkbox" checked={useFlat} onChange={() => setUseFlat(true)} />
                              Flat price
                            </label>
                            <input
                              type="number" step="1" value={flatOverride ?? ""} disabled={!useFlat}
                              placeholder="$"
                              onChange={(e) => setFlatOverride(parseFloat(e.target.value) || 0)}
                              className="w-24 px-2 py-1 rounded-md text-sm outline-none disabled:opacity-40"
                              style={{ border: `1px solid ${C.line}`, fontFamily: FONT_MONO }}
                            />
                          </div>

                          {/* receipt-style ledger, the app's signature element */}
                          <div className="rounded-lg p-3 mb-4" style={{ background: C.paper, fontFamily: FONT_MONO, fontSize: 13 }}>
                            <LedgerRow label={`${selectedVendor.format} · ${selectedVendor.strengthMg}mg × ${selectedVendor.computed.unitsNeeded}`} value={money(officeCost)} />
                            <LedgerRow label="Per-mg office rate" value={`${money(selectedVendor.computed.perMgRate)}/mg`} sub />
                            <LedgerRow label={useFlat ? "Flat patient price" : `Patient price (${multiplier}×)`} value={money(patientCost)} strong />
                            <LedgerRow label="Per-mg patient rate" value={totalMg > 0 ? `${money(patientCost / totalMg)}/mg` : "—"} sub />
                          </div>
                        </>
                      )}

                      <div className="flex gap-2">
                        <button onClick={addToPlan} className="flex items-center gap-1.5 px-3 py-2 rounded-md text-sm font-medium" style={{ background: C.successSoft, color: C.success }}>
                          <Plus size={14} /> Add to treatment plan
                        </button>
                        <button
                          onClick={saveSingleQuote}
                          disabled={!activePatientId}
                          className="flex items-center gap-1.5 px-3 py-2 rounded-md text-sm font-medium disabled:opacity-40"
                          style={{ background: C.success, color: "white" }}
                        >
                          <Save size={14} /> Save quote to patient
                        </button>
                        {!activePatientId && <span className="text-xs self-center" style={{ color: C.clay }}>Enter a patient ID above first.</span>}
                      </div>
                    </div>
                  )}
                </div>
              )}
            </div>
          </div>
        )}

        {/* ===================== TREATMENT PLAN TAB ===================== */}
        {activeTab === "plan" && (
          <div className="flex flex-col gap-4">
            <div className="rounded-xl p-4" style={{ background: C.card, border: `1px solid ${C.line}` }}>
              <SectionTitle
                eyebrow="Treatment plan"
                title={`${planCart.length} item${planCart.length === 1 ? "" : "s"} for this visit`}
                right={
                  planCart.length > 0 && (
                    <div className="flex items-center gap-2">
                      <span className="text-xs" style={{ color: C.inkSoft }}>Set all multipliers to</span>
                      <input
                        type="number" step="0.1" defaultValue={3}
                        onBlur={(e) => setAllMultipliers(parseFloat(e.target.value) || 0)}
                        className="w-16 px-2 py-1 rounded-md text-sm outline-none"
                        style={{ border: `1px solid ${C.line}`, fontFamily: FONT_MONO }}
                      />
                      <span className="text-xs" style={{ color: C.inkSoft }}>×</span>
                    </div>
                  )
                }
              />
              <p className="text-xs mb-3" style={{ color: C.inkSoft }}>
                Add each peptide course a patient is starting this visit — standard or customized, and any Custom Blends built in the next tab — as its own line, each priced independently, then save the whole visit together.
              </p>
              {planCart.length === 0 && (
                <div className="text-sm text-center py-8" style={{ color: C.inkSoft }}>
                  Nothing in this plan yet — go to Search &amp; Quote and click "Add to treatment plan," or build a Custom Blend and add it here.
                </div>
              )}
              <div className="flex flex-col gap-2">
                {planCart.map((l) => (
                  <div key={l.lineId} className="p-3 rounded-lg flex items-center justify-between gap-3" style={{ border: `1px solid ${C.line}` }}>
                    <div className="flex-1">
                      <div className="text-sm font-medium flex items-center gap-1.5">
                        {l.type === "blend" && <Tag tone="amber" icon={<FlaskConical size={11} />}>Custom blend</Tag>}
                        {l.name}
                      </div>
                      {l.type === "blend" ? (
                        <div className="text-xs mt-0.5" style={{ color: C.inkSoft, fontFamily: FONT_MONO }}>
                          {l.components.map((c) => `${c.config.doseMg}mg ${c.name}`).join(" + ")} · {l.schedule.freqPerWeek}/wk × {l.schedule.durationWeeks}wk
                        </div>
                      ) : (
                        <div className="text-xs mt-0.5" style={{ color: C.inkSoft, fontFamily: FONT_MONO }}>
                          {l.vendor.format} · {l.vendor.strengthMg}mg — {fmtMg(l.totalMg)} course · {l.unitsNeeded} unit(s)
                        </div>
                      )}
                    </div>
                    {!patientMode && (
                      <div className="flex items-center gap-2">
                        <span className="text-xs" style={{ color: C.inkSoft }}>×</span>
                        <input
                          type="number" step="0.1" value={l.multiplier}
                          onChange={(e) => updatePlanLine(l.lineId, { multiplier: parseFloat(e.target.value) || 0, flatOverride: null })}
                          className="w-16 px-2 py-1 rounded-md text-sm outline-none"
                          style={{ border: `1px solid ${C.line}`, fontFamily: FONT_MONO }}
                        />
                      </div>
                    )}
                    <div className="text-right w-28">
                      <div className="text-sm font-semibold" style={{ fontFamily: FONT_MONO, color: patientMode ? C.amber : C.ink }}>{money(l.patientCost)}</div>
                      {!patientMode && <div className="text-xs" style={{ color: C.inkSoft }}>office {money(l.officeCost)}</div>}
                    </div>
                    <button onClick={() => removePlanLine(l.lineId)} className="p-1.5 rounded-md" style={{ color: C.clay }}>
                      <X size={16} />
                    </button>
                  </div>
                ))}
              </div>

              {planCart.length > 0 && (
                <>
                  <div className="mt-4 rounded-lg p-3 flex items-center justify-between" style={{ background: C.tealSoft }}>
                    <div className="text-sm font-medium" style={{ color: C.tealDark }}>Treatment plan total</div>
                    <div className="text-right">
                      <div className="text-lg font-semibold" style={{ fontFamily: FONT_MONO, color: C.amber }}>{money(planTotals.patient)}</div>
                      {!patientMode && <div className="text-xs" style={{ color: C.tealDark }}>office cost {money(planTotals.office)}</div>}
                    </div>
                  </div>
                  <div className="flex gap-2 mt-3">
                    <button onClick={savePlanQuote} disabled={!activePatientId} className="flex items-center gap-1.5 px-3 py-2 rounded-md text-sm font-medium disabled:opacity-40" style={{ background: C.success, color: "white" }}>
                      <Save size={14} /> Save treatment plan to patient
                    </button>
                    <button onClick={() => setPlanCart([])} className="flex items-center gap-1.5 px-3 py-2 rounded-md text-sm font-medium" style={{ border: `1px solid ${C.line}`, color: C.inkSoft }}>
                      <Trash2 size={14} /> Clear plan
                    </button>
                    {!activePatientId && <span className="text-xs self-center" style={{ color: C.clay }}>Enter a patient ID above first.</span>}
                  </div>
                </>
              )}
            </div>
          </div>
        )}

        {/* ===================== CUSTOM BLEND TAB ===================== */}
        {activeTab === "customblend" && (
          <div className="grid grid-cols-12 gap-4">
            <div className="col-span-12 md:col-span-4 flex flex-col gap-4">
              <div className="rounded-xl p-3" style={{ background: C.card, border: `1px solid ${C.line}` }}>
                <SectionTitle eyebrow="Compound" title="Add peptides to this blend" />
                <div className="flex items-center gap-2 mb-2 px-2 py-1.5 rounded-md" style={{ background: C.paper }}>
                  <Search size={15} color={C.inkSoft} />
                  <input
                    value={blendComponentQuery}
                    onChange={(e) => setBlendComponentQuery(e.target.value)}
                    placeholder="Search peptide to add…"
                    className="flex-1 bg-transparent outline-none text-sm"
                    style={{ color: C.ink }}
                  />
                </div>
                <div className="flex flex-col gap-0.5 max-h-64 overflow-y-auto">
                  {blendComponentResults.map((p) => (
                    <button
                      key={p.key}
                      onClick={() => addBlendComponent(p.key)}
                      className="flex items-center justify-between px-2.5 py-2 rounded-md text-left text-sm"
                      style={{ color: C.ink }}
                    >
                      {p.displayName}
                      <Plus size={14} color={C.teal} />
                    </button>
                  ))}
                  {blendComponentResults.length === 0 && (
                    <div className="text-xs px-2 py-3" style={{ color: C.inkSoft }}>No more matching peptides to add.</div>
                  )}
                </div>
              </div>

              {blendTemplates.length > 0 && (
                <div className="rounded-xl p-3" style={{ background: C.card, border: `1px solid ${C.line}` }}>
                  <SectionTitle eyebrow="Saved blends" title="Reuse a template" />
                  <div className="flex flex-col gap-1">
                    {blendTemplates.map((t) => (
                      <div key={t.id} className="flex items-center justify-between px-2 py-1.5 rounded-md text-sm" style={{ background: C.paper }}>
                        <button onClick={() => loadBlendTemplate(t)} className="text-left flex-1" style={{ color: C.ink }}>
                          {t.name}
                          <div className="text-xs" style={{ color: C.inkSoft }}>{t.components.length} peptides · {t.freqPerWeek}/wk × {t.durationWeeks}wk</div>
                        </button>
                        <button onClick={() => deleteBlendTemplate(t.id)} className="p-1 rounded-md" style={{ color: C.clay }}>
                          <Trash2 size={13} />
                        </button>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>

            <div className="col-span-12 md:col-span-8 flex flex-col gap-4">
              <div className="rounded-xl p-4" style={{ background: C.card, border: `1px solid ${C.line}` }}>
                <SectionTitle eyebrow="Custom blend" title="A compounded formulation not in the vendor catalog" />
                <p className="text-xs mb-3" style={{ color: C.inkSoft }}>
                  Use this when you're combining two or more peptides into one reconstituted product on your own protocol — not just billing them
                  side by side. All components share one administration schedule; set each component's dose per administration below.
                </p>
                <div className="grid grid-cols-3 gap-3 mb-3">
                  <label className="flex flex-col gap-1 text-xs" style={{ color: C.inkSoft }}>
                    Blend name
                    <input
                      value={blendName}
                      onChange={(e) => setBlendName(e.target.value)}
                      placeholder={blendComponents.map((c) => c.name).join(" + ") || "e.g. Recovery Blend"}
                      className="px-2 py-1.5 rounded-md text-sm outline-none"
                      style={{ border: `1px solid ${C.line}`, color: C.ink }}
                    />
                  </label>
                  <NumField label="Shared frequency" suffix="per week" step="1" value={blendFreqPerWeek} onChange={setBlendFreqPerWeek} />
                  <div className="flex flex-col gap-1 text-xs" style={{ color: C.inkSoft }}>
                    <div className="flex items-center justify-between">
                      <span>Shared duration</span>
                      <div className="flex rounded-md overflow-hidden" style={{ border: `1px solid ${C.line}` }}>
                        {["weeks", "days"].map((u) => (
                          <button
                            key={u}
                            onClick={() => setBlendDurationUnit(u)}
                            className="px-1.5 py-0.5 text-xs"
                            style={{ background: blendDurationUnit === u ? C.teal : "transparent", color: blendDurationUnit === u ? "white" : C.inkSoft }}
                          >
                            {u}
                          </button>
                        ))}
                      </div>
                    </div>
                    <div className="flex items-center gap-1">
                      <input
                        type="number" step={blendDurationUnit === "days" ? "1" : "0.5"}
                        value={blendDurationUnit === "days" ? Math.round(blendDurationWeeks * 7 * 100) / 100 : blendDurationWeeks}
                        onChange={(e) => {
                          const v = parseFloat(e.target.value) || 0;
                          setBlendDurationWeeks(blendDurationUnit === "days" ? v / 7 : v);
                        }}
                        className="w-full px-2 py-1.5 rounded-md text-sm outline-none"
                        style={{ border: `1px solid ${C.line}`, color: C.ink, fontFamily: FONT_MONO, background: C.card }}
                      />
                      <span className="text-xs">{blendDurationUnit}</span>
                    </div>
                  </div>
                </div>
                <NumField label="Draw volume per administration (optional)" suffix="mL" step="0.05" value={blendDoseVolumeMl} onChange={setBlendDoseVolumeMl} />

                {blendComponents.length === 0 && (
                  <div className="text-sm text-center py-8 mt-3" style={{ color: C.inkSoft, border: `1px dashed ${C.line}`, borderRadius: 8 }}>
                    Add peptides from the left to start building this blend.
                  </div>
                )}

                <div className="flex flex-col gap-2 mt-3">
                  {blendComputed.map((c) => (
                    <div key={c.key} className="p-3 rounded-lg" style={{ border: `1px solid ${C.line}` }}>
                      <div className="flex items-center justify-between mb-2">
                        <div className="text-sm font-medium">{c.name}</div>
                        <button onClick={() => removeBlendComponent(c.key)} className="p-1 rounded-md" style={{ color: C.clay }}><X size={14} /></button>
                      </div>
                      <div className="grid grid-cols-3 gap-2 items-end">
                        <NumField label="Dose per administration" suffix="mg" value={c.doseMg} onChange={(v) => updateBlendComponent(c.key, { doseMg: v })} />
                        <label className="flex flex-col gap-1 text-xs col-span-2" style={{ color: C.inkSoft }}>
                          Sourced from
                          <select
                            value={c.vendorId || ""}
                            onChange={(e) => updateBlendComponent(c.key, { vendorId: e.target.value })}
                            className="px-2 py-1.5 rounded-md text-sm outline-none"
                            style={{ border: `1px solid ${C.line}`, color: C.ink, background: C.card }}
                          >
                            {c.vendorOptions.length === 0 && <option value="">No vendor pricing found</option>}
                            {c.vendorOptions.map((v) => (
                              <option key={v.id} value={v.id}>{v.format} · {v.strengthMg}mg{patientMode ? "" : ` — ${money(v.wholesalePrice)}`}</option>
                            ))}
                          </select>
                        </label>
                      </div>
                      <div className="text-xs mt-2" style={{ color: C.inkSoft, fontFamily: FONT_MONO }}>
                        {fmtMg(c.totalMg)} for full course · {c.computed.unitsNeeded} unit{c.computed.unitsNeeded === 1 ? "" : "s"}{!patientMode && ` · ${money(c.computed.costOffice)} office cost`}
                      </div>
                    </div>
                  ))}
                </div>

                {blendComponents.length > 0 && (
                  <>
                    <div className="rounded-lg p-3 my-3" style={{ background: C.paper }}>
                      <div className="text-xs uppercase tracking-wide mb-1.5" style={{ color: C.teal, letterSpacing: "0.08em" }}>Each administration contains</div>
                      <div className="text-sm" style={{ fontFamily: FONT_MONO }}>
                        {blendComponents.map((c) => `${c.doseMg}mg ${c.name}`).join(" + ")}
                      </div>
                      {blendDoseVolumeMl > 0 && (
                        <div className="text-xs mt-1" style={{ color: C.inkSoft, fontFamily: FONT_MONO }}>
                          Draw volume: {blendDoseVolumeMl}mL (~{blendDoseUnits} units on a U-100 insulin syringe)
                        </div>
                      )}
                    </div>

                    {patientMode ? (
                      <>
                        <div className="rounded-lg p-5 mb-3 text-center" style={{ background: C.tealSoft }}>
                          <div className="text-xs uppercase tracking-wide mb-1" style={{ color: C.inkSoft, letterSpacing: "0.08em" }}>Cost to patient</div>
                          <div className="text-3xl font-semibold" style={{ fontFamily: FONT_MONO, color: C.amber }}>{money(blendPatientTotal)}</div>
                        </div>
                        <div className="flex items-center gap-2 mb-3">
                          <span className="text-sm" style={{ color: C.inkSoft }}>Adjust this price</span>
                          <input
                            type="number" step="1"
                            value={blendUseFlat && blendFlatOverride != null ? blendFlatOverride : Math.round(blendPatientTotal)}
                            onChange={(e) => { setBlendUseFlat(true); setBlendFlatOverride(parseFloat(e.target.value) || 0); }}
                            className="w-28 px-2 py-1.5 rounded-md text-sm outline-none"
                            style={{ border: `1px solid ${C.line}`, fontFamily: FONT_MONO }}
                          />
                          {blendUseFlat && (
                            <button onClick={() => { setBlendUseFlat(false); setBlendFlatOverride(null); }} className="text-xs underline" style={{ color: C.inkSoft }}>
                              Reset to standard pricing
                            </button>
                          )}
                        </div>
                      </>
                    ) : (
                      <>
                        <div className="flex flex-wrap items-center gap-3 mb-3">
                          <label className="flex items-center gap-2 text-sm">
                            <input type="checkbox" checked={!blendUseFlat} onChange={() => setBlendUseFlat(false)} />
                            Multiplier
                          </label>
                          <input
                            type="number" step="0.1" value={blendMultiplier} disabled={blendUseFlat}
                            onChange={(e) => setBlendMultiplier(parseFloat(e.target.value) || 0)}
                            className="w-20 px-2 py-1 rounded-md text-sm outline-none disabled:opacity-40"
                            style={{ border: `1px solid ${C.line}`, fontFamily: FONT_MONO }}
                          />
                          <span className="text-sm" style={{ color: C.inkSoft }}>— or —</span>
                          <label className="flex items-center gap-2 text-sm">
                            <input type="checkbox" checked={blendUseFlat} onChange={() => setBlendUseFlat(true)} />
                            Flat price
                          </label>
                          <input
                            type="number" step="1" value={blendFlatOverride ?? ""} disabled={!blendUseFlat}
                            placeholder="$"
                            onChange={(e) => setBlendFlatOverride(parseFloat(e.target.value) || 0)}
                            className="w-24 px-2 py-1 rounded-md text-sm outline-none disabled:opacity-40"
                            style={{ border: `1px solid ${C.line}`, fontFamily: FONT_MONO }}
                          />
                        </div>

                        <div className="rounded-lg p-3 mb-3" style={{ background: C.tealSoft }}>
                          <LedgerRow label="Combined office cost" value={money(blendOfficeTotal)} />
                          <LedgerRow label={blendUseFlat ? "Flat patient price" : `Patient price (${blendMultiplier}×)`} value={money(blendPatientTotal)} strong />
                        </div>
                      </>
                    )}

                    <div className="flex flex-wrap gap-2">
                      <button onClick={addBlendToPlan} className="flex items-center gap-1.5 px-3 py-2 rounded-md text-sm font-medium" style={{ background: C.successSoft, color: C.success }}>
                        <Plus size={14} /> Add blend to treatment plan
                      </button>
                      <button onClick={saveCustomBlendQuote} disabled={!activePatientId} className="flex items-center gap-1.5 px-3 py-2 rounded-md text-sm font-medium disabled:opacity-40" style={{ background: C.success, color: "white" }}>
                        <Save size={14} /> Save blend directly to patient
                      </button>
                      <button onClick={saveBlendTemplate} className="flex items-center gap-1.5 px-3 py-2 rounded-md text-sm font-medium" style={{ border: `1px solid ${C.amber}`, color: C.amber, background: C.amberSoft }}>
                        Save as reusable template
                      </button>
                      <button onClick={resetBlendBuilder} className="flex items-center gap-1.5 px-3 py-2 rounded-md text-sm font-medium" style={{ border: `1px solid ${C.line}`, color: C.inkSoft }}>
                        <Trash2 size={14} /> Clear
                      </button>
                    </div>
                    {!activePatientId && <div className="text-xs mt-2" style={{ color: C.clay }}>Enter a patient ID above to save this blend directly to a record.</div>}
                  </>
                )}
              </div>
            </div>
          </div>
        )}

        {/* ===================== HISTORY TAB ===================== */}
        {activeTab === "history" && (
          <div className="rounded-xl p-4" style={{ background: C.card, border: `1px solid ${C.line}` }}>
            <SectionTitle eyebrow="Patient history" title={activePatientId ? `Record for ${activePatientId}` : "No patient loaded"} />
            {!activePatientId && <div className="text-sm" style={{ color: C.inkSoft }}>Enter a patient ID at the top of the page to view their quote history.</div>}
            {activePatientId && historyList.length === 0 && <div className="text-sm" style={{ color: C.inkSoft }}>No saved quotes yet for this patient.</div>}
            <div className="flex flex-col gap-2">
              {historyList.map((r) => (
                <div key={r.id} className="p-3 rounded-lg" style={{ border: `1px solid ${C.line}` }}>
                  <div className="flex items-center justify-between mb-1.5">
                    <div className="text-sm font-medium">
                      {r.type === "plan" ? "Treatment plan" : r.type === "customblend" ? `Custom blend — ${r.blendName}` : r.lines[0].name}
                      <span className="ml-2 text-xs" style={{ color: C.inkSoft }}>
                        {new Date(r.timestamp).toLocaleString()} · {r.doctor}
                      </span>
                    </div>
                    <div className="flex items-center gap-3">
                      <div className="text-sm font-semibold" style={{ fontFamily: FONT_MONO }}>{money(r.totalPatient)}</div>
                      <button
                        onClick={() => { setExportRecord(r); setActiveTab("export"); }}
                        className="text-xs px-2 py-1 rounded-md"
                        style={{ border: `1px solid ${C.line}`, color: C.teal }}
                      >
                        Preview / Export
                      </button>
                    </div>
                  </div>
                  <div className="text-xs" style={{ color: C.inkSoft }}>
                    {r.lines.map((l) => l.name).join(" + ")} · office {money(r.totalOffice)}
                  </div>
                </div>
              ))}
            </div>
            {historyList.length > 0 && (
              <div className="flex items-center gap-1.5 mt-3 text-xs" style={{ color: C.inkSoft }}>
                <HistoryIcon size={12} /> Records are permanent — nothing here can be edited or deleted; a change creates a new entry.
              </div>
            )}
          </div>
        )}

        {/* ===================== IMPORT TAB ===================== */}
        {activeTab === "import" && (
          <div className="flex flex-col gap-4">
            <div className="rounded-xl p-4" style={{ background: C.card, border: `1px solid ${C.line}` }}>
              <SectionTitle eyebrow="Data" title="Import your real catalog" />
              <p className="text-sm mb-4" style={{ color: C.inkSoft }}>
                Export your vendor pricing sheet and protocol sheet as CSV, then upload them here. Peptide names don't need to match
                exactly between the two files — punctuation and spacing differences (like "Melanotan-2" vs "Melanotan 2") are
                matched automatically.
              </p>
              <div className="grid grid-cols-2 gap-4">
                <div className="p-3 rounded-lg" style={{ border: `1px dashed ${C.line}` }}>
                  <div className="text-sm font-medium mb-1">Vendor pricing CSV</div>
                  <div className="text-xs mb-2" style={{ color: C.inkSoft }}>Columns: product name, format, strength (mg), wholesale price</div>
                  <label className="flex items-center gap-2 px-3 py-2 rounded-md text-sm cursor-pointer w-fit" style={{ background: C.tealSoft, color: C.tealDark }}>
                    <Upload size={14} /> Choose file
                    <input type="file" accept=".csv" className="hidden" onChange={(e) => handleVendorFile(e.target.files[0])} />
                  </label>
                  {importStatus.vendors && <div className="text-xs mt-2" style={{ color: C.teal }}>{importStatus.vendors}</div>}
                </div>
                <div className="p-3 rounded-lg" style={{ border: `1px dashed ${C.line}` }}>
                  <div className="text-sm font-medium mb-1">Protocol CSV</div>
                  <div className="text-xs mb-2" style={{ color: C.inkSoft }}>Columns: product name, dose (mg), frequency/week, duration (weeks)</div>
                  <label className="flex items-center gap-2 px-3 py-2 rounded-md text-sm cursor-pointer w-fit" style={{ background: C.tealSoft, color: C.tealDark }}>
                    <Upload size={14} /> Choose file
                    <input type="file" accept=".csv" className="hidden" onChange={(e) => handleProtocolFile(e.target.files[0])} />
                  </label>
                  {importStatus.protocols && <div className="text-xs mt-2" style={{ color: C.teal }}>{importStatus.protocols}</div>}
                </div>
              </div>
              <button onClick={resetSampleData} className="mt-4 text-xs px-3 py-1.5 rounded-md" style={{ border: `1px solid ${C.line}`, color: C.inkSoft }}>
                Reset to sample data
              </button>
            </div>

            {(unmatchedProtocolOnly.length > 0 || unmatchedVendorOnly.length > 0) && (
              <div className="rounded-xl p-4" style={{ background: C.claySoft, border: `1px solid ${C.line}` }}>
                <SectionTitle eyebrow="Gaps found" title="Unmatched entries" />
                {unmatchedProtocolOnly.length > 0 && (
                  <div className="mb-2 text-sm" style={{ color: C.clay }}>
                    <strong>{unmatchedProtocolOnly.length}</strong> peptide{unmatchedProtocolOnly.length === 1 ? "" : "s"} have a protocol but no matching vendor listing: {unmatchedProtocolOnly.map((p) => p.displayName).join(", ")}
                  </div>
                )}
                {unmatchedVendorOnly.length > 0 && (
                  <div className="text-sm" style={{ color: C.clay }}>
                    <strong>{unmatchedVendorOnly.length}</strong> vendor item{unmatchedVendorOnly.length === 1 ? "" : "s"} have pricing but no matching protocol: {unmatchedVendorOnly.map((p) => p.displayName).join(", ")}
                  </div>
                )}
              </div>
            )}
            <div className="text-xs px-1" style={{ color: C.inkSoft }}>
              Note: this is a working prototype using sample data structured to match your proposal. It runs entirely in this browser session (with your quote history saved locally) — it isn't yet connected to your live Google Sheets or a Netlify backend.
            </div>
          </div>
        )}

        {/* ===================== EXPORT TAB ===================== */}
        {activeTab === "export" && (
          <div className="flex flex-col gap-4">
            <div className="print-hide rounded-xl p-4 flex flex-wrap items-center gap-3" style={{ background: C.card, border: `1px solid ${C.line}` }}>
              <button onClick={() => { setExportPreset("internal"); setFields({ protocol: true, vendor: true, perMg: true, office: true, patient: true }); }}
                className="px-3 py-1.5 rounded-md text-sm font-medium" style={{ background: exportPreset === "internal" ? C.teal : C.paper, color: exportPreset === "internal" ? "white" : C.ink }}>
                Internal copy
              </button>
              <button onClick={() => { setExportPreset("patient"); setFields({ protocol: true, vendor: true, perMg: false, office: false, patient: true }); }}
                className="px-3 py-1.5 rounded-md text-sm font-medium" style={{ background: exportPreset === "patient" ? C.teal : C.paper, color: exportPreset === "patient" ? "white" : C.ink }}>
                Patient copy
              </button>
              <div className="flex items-center gap-3 ml-2 text-xs" style={{ color: C.inkSoft }}>
                {(exportPreset === "patient" ? ["protocol", "vendor", "patient"] : Object.keys(fields)).map((f) => (
                  <label key={f} className="flex items-center gap-1">
                    <input type="checkbox" checked={fields[f]} onChange={() => setFields((s) => ({ ...s, [f]: !s[f] }))} />
                    {{ protocol: "Protocol", vendor: "Product option", perMg: "Per-mg", office: "Office cost", patient: "Patient price" }[f]}
                  </label>
                ))}
              </div>
              <button onClick={() => window.print()} disabled={!exportRecord} className="ml-auto flex items-center gap-1.5 px-3 py-1.5 rounded-md text-sm font-medium disabled:opacity-40" style={{ background: C.tealDark, color: "white" }}>
                <Printer size={14} /> Print / Save as PDF
              </button>
            </div>

            {!exportRecord && (
              <div className="rounded-xl p-8 text-center" style={{ background: C.card, border: `1px dashed ${C.line}`, color: C.inkSoft }}>
                Select a saved quote from Patient History to preview an export.
              </div>
            )}

            {exportRecord && (
              <div className="rounded-xl p-6" style={{ background: C.card, border: `1px solid ${C.line}`, position: "relative", overflow: "hidden" }}>
                <img
                  src={LOGO_FULL}
                  alt=""
                  style={{
                    position: "absolute", top: "50%", left: "50%", transform: "translate(-50%,-50%)",
                    width: "min(75%, 520px)", opacity: 0.07, pointerEvents: "none", zIndex: 0, filter: "grayscale(1)",
                  }}
                />
                <div style={{ position: "relative", zIndex: 1 }}>
                <div className="flex items-center justify-between mb-4 pb-3" style={{ borderBottom: `2px solid ${C.tealDark}` }}>
                  <div className="flex items-center gap-2.5">
                    <img src={LOGO_MARK} alt="" className="h-8 w-auto" />
                    <div>
                      <div className="text-lg" style={{ fontFamily: FONT_DISPLAY, fontWeight: 600, color: C.ink }}>
                        <span style={{ fontFamily: FONT_ACCENT, fontStyle: "italic", fontWeight: 500 }}>The</span> Gajer Practice
                      </div>
                      <div className="text-xs" style={{ color: C.inkSoft }}>{exportPreset === "internal" ? "Internal record" : "Patient copy"}</div>
                    </div>
                  </div>
                  <div className="text-right text-xs" style={{ color: C.inkSoft }}>
                    <div>Patient ID: <strong>{exportRecord.patientId}</strong></div>
                    <div>{new Date(exportRecord.timestamp).toLocaleDateString()} · {exportRecord.doctor}</div>
                  </div>
                </div>
                {exportRecord.type === "customblend" && (
                  <div className="text-xs mb-3 px-3 py-2 rounded-md" style={{ background: C.tealSoft, color: C.tealDark }}>
                    <strong>{exportRecord.blendName}</strong> — combined dose {exportRecord.schedule.freqPerWeek}/week for {exportRecord.schedule.durationWeeks} weeks
                    {exportRecord.schedule.doseVolumeMl > 0 && ` · draw volume ${exportRecord.schedule.doseVolumeMl}mL (~${Math.round(exportRecord.schedule.doseVolumeMl * 100)} units)`}
                  </div>
                )}
                <div className="flex flex-col gap-3">
                  {exportRecord.lines.map((l, i) => (
                    <div key={i} className="p-3 rounded-lg" style={{ background: C.paper }}>
                      {l.groupLabel && (
                        <div className="text-xs mb-1 font-medium" style={{ color: C.amber }}>{l.groupLabel} (custom blend component)</div>
                      )}
                      <div className="text-sm font-semibold mb-1">{l.name}</div>
                      {fields.protocol && (
                        <div className="text-xs mb-1" style={{ color: C.inkSoft }}>
                          {l.config.doseMg}mg × {l.config.freqPerWeek}/week for {l.config.durationWeeks} weeks — total {fmtMg(l.totalMg)}
                        </div>
                      )}
                      {fields.vendor && <div className="text-xs mb-1" style={{ color: C.inkSoft }}>Product: {l.vendor.format}, {l.vendor.strengthMg}mg ({l.unitsNeeded} unit{l.unitsNeeded === 1 ? "" : "s"})</div>}
                      {fields.perMg && <div className="text-xs mb-1" style={{ color: C.inkSoft, fontFamily: FONT_MONO }}>{money(l.vendor.wholesalePrice / l.vendor.strengthMg)}/mg office</div>}
                      <div className="flex gap-4 mt-1">
                        {fields.office && <div className="text-sm" style={{ fontFamily: FONT_MONO }}>Office: {money(l.officeCost)}</div>}
                        {fields.patient && <div className="text-sm font-semibold" style={{ fontFamily: FONT_MONO, color: C.amber }}>Patient: {money(l.patientCost)}</div>}
                      </div>
                    </div>
                  ))}
                </div>
                <div className="flex justify-end gap-6 mt-4 pt-3" style={{ borderTop: `1px solid ${C.line}` }}>
                  {fields.office && <div className="text-sm">Total office: <strong style={{ fontFamily: FONT_MONO }}>{money(exportRecord.totalOffice)}</strong></div>}
                  {fields.patient && <div className="text-base font-semibold" style={{ color: C.amber }}>Total: <span style={{ fontFamily: FONT_MONO }}>{money(exportRecord.totalPatient)}</span></div>}
                </div>
                </div>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

function LedgerRow({ label, value, sub, strong }) {
  return (
    <div
      className="flex items-baseline justify-between"
      style={{
        padding: sub ? "1px 0" : "4px 0",
        opacity: sub ? 0.65 : 1,
        marginTop: strong ? 4 : 0,
        borderTop: strong ? `1px dashed ${C.line}` : "none",
        paddingTop: strong ? 6 : undefined,
      }}
    >
      <span style={{ fontSize: sub ? 11 : 13, color: sub ? C.inkSoft : C.ink }}>{label}</span>
      <span style={{ fontSize: sub ? 11 : strong ? 15 : 13, fontWeight: strong ? 700 : 500, color: strong ? C.amber : C.ink }}>{value}</span>
    </div>
  );
}
